function initHeaderScroll(){let e=document.querySelector(".header");if(!e)return;let t=!1;window.addEventListener("scroll",()=>{t||(window.requestAnimationFrame(()=>{window.scrollY>40?e.classList.add("scrolled"):e.classList.remove("scrolled"),t=!1}),t=!0)},{passive:!0})}function initCopyEmail(){let e=document.getElementById("copy-email-btn"),t=document.getElementById("email-text");e&&t&&e.addEventListener("click",()=>{navigator.clipboard.writeText("contact@stargolab.com.br").then(()=>{let e=t.innerText;t.innerText="✓ E-mail copiado!",setTimeout(()=>{t.innerText=e},2e3)}).catch(e=>{console.error("Erro ao copiar e-mail: ",e)})})}document.addEventListener("DOMContentLoaded",()=>{initHeaderScroll(),initCopyEmail()}),document.addEventListener("DOMContentLoaded",()=>{let e={root:null,rootMargin:"0px 0px -50px 0px",threshold:.15},t=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("active"),t.unobserve(e.target))})},e),r=document.querySelectorAll(".reveal");r.forEach(e=>t.observe(e))});